-- PT113-S3-Q1. Batch 06.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch06$PT113-S3-Q1$batch06$ AND q.stimulus=$batch06$Moralist: TV talk shows are contributing to the moral decline in our country. By constantly being shown the least moral people in our society, viewers begin to think that such people are the norm, and that there is something wrong with being morally upright.TV talk show host: Well, if there is such a decline, it’s not because of TV talk shows: we simply show people what they want to see. What can be wrong with letting the viewers decide? Furthermore, if restrictions were put on my show, that would amount to censorship, which is wrong.$batch06$ AND q.prompt=$batch06$The moralist's and the TV talk show host's statements provide the most support for holding that they disagree about whether$batch06$ AND q.correct_choice=$batch06$D$batch06$) THEN RAISE EXCEPTION 'Question changed: PT113-S3-Q1'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch06$PT113-S3-Q1$batch06$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT113-S3-Q1'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch06$PT113-S3-Q1$batch06$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch06$Moralist's Position$batch06$, $batch06$TV talk shows are contributing to moral decline by showing the least moral people as normal.$batch06$), (1, $batch06$Talk show host's Position$batch06$, $batch06$If there is a decline, talk shows are not the cause. They show people what they want to see, and restricting them would be censorship.$batch06$), (2, $batch06$Evaluate$batch06$, $batch06$The moralist's main claim is causal: the shows are causing decline. The host's first move denies exactly that. The censorship point is the host's alone. The moralist never proposes restrictions.$batch06$), (3, $batch06$Goal$batch06$, $batch06$Whether talk shows are causing a moral decline.$batch06$)) v(position,label,body) WHERE q.qid=$batch06$PT113-S3-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch06$A$batch06$, $batch06$The host brings up censorship, but the moralist never says the shows should be censored.$batch06$), ($batch06$B$batch06$, $batch06$The host says "*if* there is such a decline." He neither accepts nor denies that standards have changed.$batch06$), ($batch06$C$batch06$, $batch06$This is the most popular wrong answer. The moralist says the shows shape viewers' sense of what is normal. But the host never denies that influence. He denies that the shows cause a *decline*.$batch06$), ($batch06$D$batch06$, $batch06$The moralist says the shows are causing decline. The host says "it's not because of TV talk shows."$batch06$), ($batch06$E$batch06$, $batch06$The host thinks letting viewers decide is fine. The moralist never takes a position on it.$batch06$)) v(letter,body) WHERE q.qid=$batch06$PT113-S3-Q1$batch06$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
